def longest_common_prefix(strings):
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        prefix = prefix[:min(len(prefix), len(s))]
        while prefix and s[0]!= prefix[0]:
            prefix = prefix[:-1]
    return prefix

