def join_tuples(tuples):
    result = []
    for t in tuples:
        found = False
        for r in result:
            if t[0] in r:
                r.remove(t[0])
                r.append(t)
                found = True
                break
        if not found:
            result.append(t)
    return result

def filter_dict(dct, func):
    """
    Returns a new dictionary with the same keys as dct, but only containing the values that
    pass the test implemented by the function func.
    """
    return {key: value for key, value in dct.items() if func(value)}

def first_repeated_word(sentence):
    words_dict = {}
    for word in sentence.split():
        if word in words_dict:
            return word
        words_dict[word] = 1
    return None

