def kth_element(arr1, arr2, k):
    i = 0
    j = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            i += 1
        else:
            if k == 0:
                return arr1[i]
            k -= 1
            j += 1
    return arr2[j] if k == 0 else None

def power(a, b):
    if b == 0:
        return 1
    elif b == 1:
        return a
    elif b % 2 == 0:
        return power(a * a, b // 2)
    else:
        return a * power(a * a, b // 2)

