def num_ways_to_fill(n):
    """
    Return the number of ways to fill a 3xn board with 2x1 dominoes.
    """
    if n == 0:
        return 1  # There is only one way to fill a 3x0 board (with no dominoes)

    ways = 0
    for i in range(n):
        # For each possible position for the first domino
        for j in range(3):
            # For each possible orientation of the first domino
            for k in range(2):
                # Recursively count the number of ways to fill the rest of the board
                ways += num_ways_to_fill(n-1)

    return ways

def odd_occurrences(arr):
    # Create a dictionary to count the occurrences of each element
    count = {}
    for num in arr:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Initialize an empty list to store the elements with odd occurrences
    result = []

    # Iterate through the dictionary and append the elements with odd occurrences to the result list
    for num in count:
        if count[num] % 2!= 0:
            result.append(num)

    return result

